// 取得上一個節點的 HTML
const html = $input.first().json.data;

// 方法1: 直接匹配包含這三個 class 的 <a> 標籤的 href
const linkRegex = /<a[^>]*href="([^"]+)"[^>]*class="[^"]*container__link[^"]*container__link--type-article[^"]*container_lead-plus-headlines__link[^"]*"[^>]*>/g;

let results = [];
let match;

while ((match = linkRegex.exec(html)) !== null) {
    const href = match[1];
    results.push({ href });
}

return results;

// 處理單個項目
const href = $json.href;

// 獲取當前日期 - 如果沒有 currentDate，使用當前時間
let currentDate;
if ($json.currentDate) {
    currentDate = $json.currentDate;
} else {
    // 使用當前時間（台北時區 +8）
    const now = new Date();
    currentDate = now.toISOString();
}

// 計算昨日日期
const today = new Date(currentDate);
const yesterday = new Date(today);
yesterday.setDate(today.getDate() - 1); // 減一天

// 格式化昨日日期 (格式: YYYY/MM/DD)
const yesterdayString = `/${yesterday.getFullYear()}/${String(yesterday.getMonth() + 1).padStart(2, '0')}/${String(yesterday.getDate()).padStart(2, '0')}/`;

// 檢查這個 href 是否包含昨日日期
if (href && href.includes(yesterdayString)) {
    // 如果包含昨日日期，返回這個項目
    return { href: href };
} else {
    // 如果不包含昨日日期，返回 null（n8n 會跳過這個項目）
    return null;
}

// n8n環境下提取指定class內容的函數
function extractContent(data) {
    let htmlString = '';

    // 處理不同類型的輸入數據
    if (typeof data === 'string') {
        htmlString = data;
    } else if (typeof data === 'object' && data !== null) {
        // 如果是對象，嘗試找到HTML內容
        if (data.html) htmlString = data.html;
        else if (data.content) htmlString = data.content;
        else if (data.data) htmlString = data.data;
        else if (data.body) htmlString = data.body;
        else htmlString = JSON.stringify(data);
    }

    // 提取標題內容 - 使用更寬鬆的匹配
    const titleRegex = /<[^>]*class="[^"]*headline__text[^"]*"[^>]*>(.*?)<\/[^>]+>/gs;
    const titles = [];
    let titleMatch;

    while ((titleMatch = titleRegex.exec(htmlString)) !== null) {
        let content = titleMatch[1];
        content = content.replace(/<[^>]*>/g, '');
        content = content
            .replace(/&amp;/g, '&')
            .replace(/&lt;/g, '<')
            .replace(/&gt;/g, '>')
            .replace(/&quot;/g, '"')
            .replace(/&#39;/g, "'")
            .replace(/&nbsp;/g, ' ');
        content = content.replace(/\s+/g, ' ').trim();

        if (content) {
            titles.push(content);
        }
    }

    // 提取段落內容 - 使用更寬鬆的匹配
    const paragraphRegex = /<[^>]*class="[^"]*paragraph-elevate[^"]*"[^>]*>(.*?)<\/[^>]+>/gs;
    const paragraphs = [];
    let paragraphMatch;

    while ((paragraphMatch = paragraphRegex.exec(htmlString)) !== null) {
        let content = paragraphMatch[1];
        content = content.replace(/<[^>]*>/g, '');
        content = content
            .replace(/&amp;/g, '&')
            .replace(/&lt;/g, '<')
            .replace(/&gt;/g, '>')
            .replace(/&quot;/g, '"')
            .replace(/&#39;/g, "'")
            .replace(/&nbsp;/g, ' ');
        content = content.replace(/\s+/g, ' ').trim();

        if (content) {
            paragraphs.push(content);
        }
    }

    return {
        title: titles.join(' '),  // 只包含headline__text的內容
        merged: paragraphs.join(' ')  // 只包含段落內容，不包含標題
    };
}

// 更寬鬆的匹配方式（如果上面的正則太嚴格）
function extractContentLoose(data) {
    let htmlString = '';

    if (typeof data === 'string') {
        htmlString = data;
    } else if (typeof data === 'object' && data !== null) {
        if (data.html) htmlString = data.html;
        else if (data.content) htmlString = data.content;
        else if (data.data) htmlString = data.data;
        else if (data.body) htmlString = data.body;
        else htmlString = JSON.stringify(data);
    }

    // 提取標題（寬鬆匹配）
    const titleRegex = /<[^>]*class="[^"]*(?=.*headline__text)(?=.*inline-placeholder)(?=.*vossi-headline-text)[^"]*"[^>]*>(.*?)<\/[^>]+>/gs;
    const titles = [];
    let titleMatch;

    while ((titleMatch = titleRegex.exec(htmlString)) !== null) {
        let content = titleMatch[1];
        content = content.replace(/<[^>]*>/g, '');
        content = content
            .replace(/&amp;/g, '&')
            .replace(/&lt;/g, '<')
            .replace(/&gt;/g, '>')
            .replace(/&quot;/g, '"')
            .replace(/&#39;/g, "'")
            .replace(/&nbsp;/g, ' ');
        content = content.replace(/\s+/g, ' ').trim();

        if (content) {
            titles.push(content);
        }
    }

    // 提取段落（寬鬆匹配）
    const paragraphRegex = /<[^>]*class="[^"]*(?=.*paragraph-elevate)(?=.*inline-placeholder)(?=.*vossi-paragraph)[^"]*"[^>]*>(.*?)<\/[^>]+>/gs;
    const paragraphs = [];
    let paragraphMatch;

    while ((paragraphMatch = paragraphRegex.exec(htmlString)) !== null) {
        let content = paragraphMatch[1];
        content = content.replace(/<[^>]*>/g, '');
        content = content
            .replace(/&amp;/g, '&')
            .replace(/&lt;/g, '<')
            .replace(/&gt;/g, '>')
            .replace(/&quot;/g, '"')
            .replace(/&#39;/g, "'")
            .replace(/&nbsp;/g, ' ');
        content = content.replace(/\s+/g, ' ').trim();

        if (content) {
            paragraphs.push(content);
        }
    }

    return {
        title: titles.join(' '),  // 只包含headline__text的內容
        merged: paragraphs.join(' ')  // 只包含段落內容，不包含標題
    };
}

// n8n使用示例 - 將以下代碼直接放在Code節點中

// 獲取輸入數據
const inputData = $json.data;

// 提取內容
const result = extractContent(inputData);

// 如果第一種方法沒有結果，嘗試更寬鬆的匹配
if (!result.title && !result.merged) {
    const looseResult = extractContentLoose(inputData);
    return {
        title: looseResult.title,
        merged: looseResult.merged
    };
}

// 返回結果
return {
    title: result.title,
    merged: result.merged
};

